style.css:
@-moz-document domain("youtube.com") {
/* Background + Font */
  body, ytd-app {
    background: url("https://www.transparenttextures.com/patterns/black-felt.png") repeat !important;
    color: #e2d6c2 !important;
    font-family: 'UnifrakturCook', cursive !important;
  }

  /* Topbar - Dark Castle Vibes */
  ytd-masthead {
    background: linear-gradient(to right, #1a1a1a, #2d1e1e) !important;
    border-bottom: 3px solid #5b2a2a !important;
    box-shadow: 0 4px 6px #000 !important;
    position: relative;
  }

  /* Torch Flames (GIFs) */
  ytd-masthead::before,
  ytd-masthead::after {
    content: "";
    position: absolute;
    top: 10px;
    width: 30px;
    height: 60px;
    background: url("https://i.imgur.com/JtKQkrL.gif") no-repeat center center;
    background-size: cover;
    z-index: 1000;
    pointer-events: none;
  }

  ytd-masthead::before {
    left: 10px;
  }

  ytd-masthead::after {
    right: 10px;
  }

  /* Gothic Dropdowns (no animation since Stylish blocks @keyframes sometimes) */
  tp-yt-paper-dialog, ytd-popup-container {
    background: #2a1a1a !important;
    border: 2px solid #8c6239 !important;
    border-radius: 5px;
    box-shadow: inset 0 0 15px #1b0a0a, 0 0 15px #000 !important;
    font-family: 'UnifrakturCook', cursive !important;
  }

  /* Hide Shorts and Explore */
  ytd-mini-guide-entry-renderer[aria-label="Shorts"],
  ytd-mini-guide-entry-renderer[aria-label="Explore"],
  ytd-rich-shelf-renderer[is-shorts],
  ytd-guide-entry-renderer[aria-label="Shorts"] {
    display: none !important;
  }

  /* Video titles medieval */
  a#video-title {
    font-family: 'UnifrakturCook', cursive !important;
    color: #e2d6c2 !important;
    text-shadow: 1px 1px #000;
  }

  /* Search bar + buttons */
  input#search,
  tp-yt-paper-button,
  ytd-button-renderer {
    background-color: #331111 !important;
    color: #d0bfae !important;
    border: 1px solid #7a3f3f !important;
    font-family: 'UnifrakturCook', cursive !important;
    border-radius: 0px !important;
  }

  /* Sidebar */
  #guide-inner-content {
    background: #1a1a1a !important;
    border-right: 2px solid #552222 !important;
  }

  /* Gothic scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #0d0d0d;
  }

  ::-webkit-scrollbar-thumb {
    background: #552222;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #993333;
  }
}
